import java.util.*;
public class LinearProbingHashTable { String[] a=new String[7]; boolean[] deleted=new boolean[7]; int hash(String s){return Math.abs(s.hashCode())%a.length;} void add(String s){int i=hash(s);while(a[i]!=null)i=(i+1)%a.length;a[i]=s;} boolean contains(String s){int i=hash(s),steps=0;while(steps++<a.length&&(a[i]!=null||deleted[i])){if(s.equals(a[i]))return true;i=(i+1)%a.length;}return false;} public static void run(){LinearProbingHashTable h=new LinearProbingHashTable();for(String s:new String[]{"A","H","O"})h.add(s);System.out.println("Linear probing table="+Arrays.toString(h.a)+", contains H="+h.contains("H"));System.out.println("Invariant: probe sequence continues through occupied and deleted slots.\n");} public static void main(String[] args){run();}}
